/** Every entry whose figure needs a second pair of eyes. Drives NEEDS_VERIFICATION.md. */
export const LOW_CONFIDENCE = PLAYERS.filter((p) => p.confidence === 'low')

export function playersForSport(sport: Player['sport']): Player[] {
  return PLAYERS.filter((p) => p.sport === sport)
}
